import re

def word_frequency(text: str) -> dict[str, int]:
    words = re.findall(r'\b\w+\b', text.lower())
    frequency = {}
    for word in words:
        if word in frequency:
            frequency[word] += 1
        else:
            frequency[word] = 1
    return frequency

